require "forwardable"
require "capybara/cuprite/finder"
require "capybara/cuprite/driver/deprecations"
require "capybara/cuprite/driver/extensions"

module Capybara
  module Cuprite
    class Driver < Capybara::Driver::Base
      DEFAULT_MAXIMIZE_SCREEN_SIZE = [1366, 768].freeze
      EXTENSION = File.expand_path("javascripts/index.js", __dir__)
      CALLBACK_JS = <<~JS
        function(...args) {
          return new Promise((resolve, reject) => {
            try {
              (function() {
                SCRIPT
              }).apply(this, [...args, resolve]);
            } catch (error) {
              reject(error);
            }
          });
        }
      JS

      extend Forwardable
      include Deprecations
      include Extensions

      delegate %i[quit current_url title
                  window_handles current_window_handle close_window switch_to_window
                  refresh] => :browser
      delegate %i[send_keys] => :active_element
      def_delegator :browser, :body, :html
      def_delegator :browser, :back, :go_back
      def_delegator :browser, :forward, :go_forward

      attr_reader :app, :options

      def initialize(app, options = {})
        @app     = app
        @options = options.dup
        @started = false

        @options[:extensions] ||= []
        @options[:extensions] << EXTENSION

        @screen_size = @options.delete(:screen_size)
        @screen_size ||= DEFAULT_MAXIMIZE_SCREEN_SIZE
        @options[:save_path] ||= File.expand_path(Capybara.save_path) if Capybara.save_path

        @options[:pending_connection_errors] = true unless @options.key?(:pending_connection_errors)

        # It's set for debug() to make devtools tab open correctly.
        @options[:browser_options] ||= {}
        unless @options[:browser_options][:"remote-allow-origins"]
          @options[:browser_options].merge!("remote-allow-origins": "*")
        end
        @options[:browser_options] = { "disable-web-security": nil }.merge(@options[:browser_options])

        super()
      end

      def needs_server?
        true
      end

      def browser
        @browser ||= Browser.new({ base_url: capybara_base_url }.compact.merge(@options))
      end

      def visit(url)
        @started = true
        browser.base_url = url if url.match?(%r{\Ahttps?://})
        browser.goto(url)
      end

      def status_code
        browser.network.status
      end

      def frame_url
        evaluate_script("window.location.href")
      end

      def frame_title
        evaluate_script("document.title")
      end

      def active_element
        Node.new(self, browser.evaluate("document.activeElement"))
      end

      def find_xpath(selector)
        find(:xpath, selector)
      end

      def find_css(selector)
        find(:css, selector)
# frozen_string_literal: true

module Capybara
  module Cuprite
    class Page < Ferrum::Page
      module Modals
        MODAL_WAIT = ENV.fetch("CUPRITE_MODAL_WAIT", 0.05).to_f

        def initialize(...)
          @accept_modal = []
          @modal_messages = []
          @modal_response = nil
          @unhandled_modal_error = nil
          super
        end

        # The `Page.javascriptDialogOpening` event is handled on Ferrum's
        # background CDP dispatcher thread, so raising there wouldn't reach
        # the caller and would permanently kill that thread instead. The
        # dialog is always accepted immediately from that thread, and the
        # error (if any) is stashed here to be raised from the main thread
        # the next time it makes a command round trip.
        def command(...)
          raise_pending_unhandled_modal_error! { super }
        end

        def accept_confirm
          @accept_modal << true
        end

        def dismiss_confirm
          @accept_modal << false
        end

        def accept_prompt(modal_response)
          @accept_modal << true
          @modal_response = modal_response
        end

        def dismiss_prompt
          @accept_modal << false
        end

        def find_modal(options)
          start = Ferrum::Utils::ElapsedTime.monotonic_time
          expect_text = options[:text]
          expect_regexp = expect_text.is_a?(Regexp) ? expect_text : Regexp.escape(expect_text.to_s)
          not_found_msg = "Unable to find modal dialog"
          not_found_msg += " with #{expect_text}" if expect_text
          wait = options.fetch(:wait, timeout)

          begin
            modal_text = @modal_messages.shift
            raise Capybara::ModalNotFound if modal_text.nil? || (expect_text && !modal_text.match(expect_regexp))
          rescue Capybara::ModalNotFound => e
            raise e, not_found_msg if Ferrum::Utils::ElapsedTime.timeout?(start, wait)

            sleep(MODAL_WAIT)
            retry
          end
