cat > script/check_browser <<'EOF'
#!/usr/bin/env ruby
require "capybara/cuprite"
require "securerandom"

Capybara.app_host = ENV.fetch("QUIZZY_URL", "http://127.0.0.1:3000")
Capybara.run_server = false
Capybara.enable_aria_label = true
Capybara.default_max_wait_time = 4
Capybara.register_driver(:quizzy) do |app|
  Capybara::Cuprite::Driver.new(app,
    browser_path: ENV.fetch("CHROMIUM_PATH", "chromium"),
    window_size: [1280, 920],
    browser_options: { "no-sandbox": nil, "disable-dev-shm-usage": nil, "disable-background-networking": nil })
end

class BrowserCheck
  def initialize
    @page = Capybara::Session.new(:quizzy)
    @browser = @page.driver.browser
    @browser.network.authorize(user: ENV.fetch("QUIZZY_MODERATOR_USERNAME"),
      password: ENV.fetch("QUIZZY_MODERATOR_PASSWORD"), &:continue)
  end

  def run
    title = "Quizzy browser check #{SecureRandom.hex(4)}"
    @page.visit("/moderate")
    @page.click_link("New quiz")
    @page.fill_in("Title", with: title)
    @page.click_button("Save quiz")
    expect(@page.has_css?("h1", text: title), "Saved quiz opens")
    @page.click_link("Preview")
    expect(@page.has_text?("No active questions"), "Empty quiz has an empty preview")
    @page.click_link("Back to quiz")

    open_question_form("Which colors are primary in light?")
    expect(@page.all(".option-row", count: 4).size == 4, "Four initial options")
    expect(@page.has_checked_field?("Active"), "Active by default")
    @page.fill_in("Option 1", with: "Green")
    @page.click_button("Save question")
    expect(@page.has_text?("Add at least two options"), "Reject a single option")
    expect(@page.has_field?("Question", with: "Which colors are primary in light?"), "Keep question text")
    expect(@page.has_field?("Option 1", with: "Green"), "Keep option text")
    @page.fill_in("Option 2", with: "Yellow")
    @page.check("Option 3 is correct")
    @page.click_button("Save question")
    expect(@page.has_text?("Mark at least one option as correct"), "A checked blank does not count")
    expect(@page.has_checked_field?("Option 3 is correct"), "Keep checkbox state on invalid form")
    @page.check("Option 1 is correct")
    @page.click_button("Add option")
    @page.fill_in("Option 5", with: "Red")
    @page.check("Option 5 is correct")
    @page.click_button("Save question")
    expect(@page.has_css?(".question-item", count: 1), "Question saved only once")
    expect(@page.has_css?(".question-item__options li", count: 3), "Blank option rows skipped")
    expect(@page.has_css?(".question-item__options .is-correct", count: 2), "Multiple correct choices marked")

    add_question("What is two plus two?", "Four", "Three")
    add_question("What is two plus three?", "Five", "Six")
    add_question("Not shown in Preview", "First", "Second")

    toggle = @page.find(".question-item", text: "Not shown in Preview")
    toggle.uncheck("Active")
    expect(@page.has_css?(".question-item--inactive", text: "Not shown in Preview"), "Active changes save")
    @page.refresh
    expect(@page.find(".question-item", text: "Not shown in Preview").has_unchecked_field?("Active"), "Inactive after reload")
    @page.find(".question-item", text: "What is two plus two?").click_button("Move up")
    expect(order.first == "What is two plus two?", "Move up swaps neighbors")
    @page.find(".question-item", text: "What is two plus two?").click_button("Move down")
    expect(order.first == "Which colors are primary in light?", "Move down swaps neighbors")
    @page.find(".question-item", text: "What is two plus three?").click_link("Edit")
    expect(@page.has_field?("Option 1", with: "Five"), "Edit loads existing options")
    @page.fill_in("Question", with: "What is three plus two?")
    @page.click_button("Save question")
    expect(@page.has_css?(".question-item", text: "What is three plus two?"), "Edit saves changes")

    @browser.resize(window: nil, width: 390, height: 844)
    @page.click_link("Preview")
    expect(@page.has_text?("Question 1 of 3"), "Preview uses active count")
    expect(@page.has_no_text?("Not shown in Preview"), "Preview excludes inactive questions")
    expect(@page.has_no_text?("What is two plus two?"), "Only one question visible")
    @page.click_button("Red", exact: true)
    expect(@page.has_text?("Correct!"), "Any correct option scores")
    expect(@page.has_css?(".is-correct", count: 2), "Reveal all correct choices")
    @page.click_button("Next question")
    expect(@page.has_text?("Question 2 of 3"), "Next question updates progress")
    @page.click_button("Three", exact: true)
    expect(@page.has_text?("Wrong!"), "Wrong answer feedback")
    @page.click_button("Next question")
    expect(@page.has_text?("What is three plus two?"), "Preview uses edited text")
    @page.click_button("Five", exact: true)
    @page.click_button("See score")
    expect(@page.has_text?("Score: 2/3"), "Final score")
    @page.click_button("Start over")
    expect(@page.has_text?("Question 1 of 3"), "Restart returns to first question")
    expect(@page.has_button?("Red", exact: true, disabled: false), "Restart clears revealed answers")
    expect(@page.has_no_text?("Score: 2/3"), "Restart hides previous score")
    @page.click_link("Back to quiz")
    @browser.resize(window: nil, width: 1280, height: 920)

    @page.within(".question-item", text: "Not shown in Preview") do
      @page.dismiss_confirm("Delete this question?") { @page.click_button("Delete", exact: true) }
    end
    expect(@page.has_css?(".question-item", text: "Not shown in Preview"), "Dismiss question delete")
    @page.within(".question-item", text: "Not shown in Preview") do
      @page.accept_confirm("Delete this question?") { @page.click_button("Delete", exact: true) }
    end
    expect(@page.has_no_css?(".question-item", text: "Not shown in Preview"), "Confirm question delete")
    @page.click_link("Settings")
    @page.fill_in("Title", with: "#{title} (renamed)")
    @page.click_button("Save quiz")
    expect(@page.has_css?("h1", text: "#{title} (renamed)"), "Rename quiz in Settings")
    @page.click_link("Settings")
    @page.dismiss_confirm("Delete this quiz and all its questions?") { @page.click_button("Delete quiz") }
    expect(@page.has_field?("Title", with: "#{title} (renamed)"), "Dismiss quiz delete")
    @page.accept_confirm("Delete this quiz and all its questions?") { @page.click_button("Delete quiz") }
    expect(@page.has_css?("h1", text: "Quizzes"), "Confirm quiz delete")
    expect(@page.has_no_link?("#{title} (renamed)"), "Deleted quiz is not listed")
    puts "Chromium moderator and preview workflow passed."
  ensure
    @browser.quit
  end

  private

  def expect(condition, message)
    raise "Failed: #{message}" unless condition
  end

  def open_question_form(body)
    @page.click_link("Add question")
    @page.fill_in("Question", with: body)
  end

  def add_question(body, correct, wrong)
    open_question_form(body)
    @page.fill_in("Option 1", with: correct)
    @page.fill_in("Option 2", with: wrong)
    @page.check("Option 1 is correct")
    @page.click_button("Save question")
    expect(@page.has_css?(".question-item", text: body), "Save #{body}")
  end

  def order
    @page.all(".question-item__body").map(&:text)
  end
end

BrowserCheck.new.run
